type Status = 'phase1' | 'future';
type Detail = { what: string; help: string; next: string; example?: string };
type Node = { id: string; label: string; status?: Status; kind?: 'expansion'; description?: string; detailText?: string; phaseStatus?: string; children?: Node[]; detail?: Detail };
type Box = { node: Node; depth: number; x: number; y: number; width: number; height: number };
type Group = { from: Box; x: number; y: number; children: Box[] };
type Layout = { width: number; height: number; boxes: Box[]; edges: { from: Box; to: Box }[]; groups: Group[] };
type PanelTab = 'overview' | 'client-work' | 'wealthgate';
type MarketView = 'immediate' | 'expansion';

