  const switchMarketView = (next: MarketView) => { setMarketView(next); if (next === 'expansion' && !expansionAreas.some(node => node.id === selected)) select('brokerage-expansion'); if (next === 'immediate' && expansionAreas.some(node => node.id === selected)) select('wm'); };
